export function KanbanBoard({
  title1 = "{{title1}}",
  title2 = "{{title2}}",
  title3 = "{{title3}}",
  thirdColumn = {{thirdColumn}},
  emptyMiddle = {{emptyMiddle}},
  accent = "{{accent}}",
}) {
  const colStyle = { background: "#FAF7F2", borderRadius: 12, padding: 14, width: 200, boxSizing: "border-box", boxShadow: "0 4px 14px rgba(36,20,48,.1)" };
  const headingStyle = { margin: "0 0 10px", fontSize: 14, fontWeight: 700, borderBottom: `3px solid ${accent}`, paddingBottom: 8 };
  const listStyle = { listStyle: "none", margin: 0, padding: 0, display: "flex", flexDirection: "column", gap: 10 };
  const cardStyle = { background: "#fff", border: "1px solid #24143020", borderRadius: 8, padding: 12, fontSize: 13, display: "flex", flexDirection: "column", gap: 6 };
  const tagStyle = { alignSelf: "flex-start", fontSize: 11, fontWeight: 600, padding: "2px 8px", borderRadius: 999, background: accent, color: "#241430" };
  return (
    <div style={{ display: "flex", gap: 16, fontFamily: "system-ui, sans-serif", color: "#241430", alignItems: "flex-start" }}>
      <div style={colStyle}>
        <h3 style={headingStyle}>{title1}</h3>
        <ul style={listStyle}>
          <li style={cardStyle}>Design onboarding flow<span style={tagStyle}>UX</span></li>
          <li style={cardStyle}>Write Q3 report<span style={tagStyle}>Docs</span></li>
        </ul>
      </div>
      <div style={colStyle}>
        <h3 style={headingStyle}>{title2}</h3>
        {emptyMiddle ? (
          <p style={{ margin: 0, padding: "20px 8px", textAlign: "center", fontSize: 12.5, color: "#241430aa", border: "1.5px dashed #24143033", borderRadius: 8 }}>No cards yet</p>
        ) : (
          <ul style={listStyle}>
            <li style={cardStyle}>Refactor auth module<span style={tagStyle}>Eng</span></li>
            <li style={cardStyle}>Update pricing copy<span style={tagStyle}>Marketing</span></li>
          </ul>
        )}
      </div>
      {thirdColumn && (
        <div style={colStyle}>
          <h3 style={headingStyle}>{title3}</h3>
          <ul style={listStyle}>
            <li style={cardStyle}>Ship landing page<span style={tagStyle}>Eng</span></li>
            <li style={cardStyle}>Customer interview notes<span style={tagStyle}>Research</span></li>
          </ul>
        </div>
      )}
    </div>
  );
}
